pub struct JsManager;

impl JsManager {
    pub fn optional_plugin_stub() -> &'static str {
        "data:text/javascript,/* autogenerated missing optional plugin stub */const m=new Proxy({},{get:()=>null});export default new Proxy({},{get:()=>m});"
    }

    pub fn required_plugin_stub(plugin_name: &str) -> String {
        let message = format!("Plugin '{}' is imported by another bundle, but it is not installed on this site. If this dependency is optional, import it with `with {{ discourseImport: \"optional\" }}`.", plugin_name);
        format!("data:text/javascript, /* autogenerated missing required plugin stub */ export default null; throw new Error({});", serde_json::to_string(&message).unwrap_or_else(|_| "\"Error\"".to_string()))
    }

    pub fn js_asset_exists(_plugin_directory_name: &str) -> bool { false }
    pub fn admin_js_asset_exists(_plugin_directory_name: &str) -> bool { false }
    pub fn test_js_asset_exists(_plugin_directory_name: &str) -> bool { false }
    pub fn read_manifest(_plugin_directory_name: &str) -> std::collections::HashMap<String, String> { std::collections::HashMap::new() }
    pub fn bundle_analysis_assets() -> std::collections::HashMap<String, String> { std::collections::HashMap::new() }

    pub fn logical_path(file_name: &str) -> String {
        let stripped = if file_name.ends_with(".js") { &file_name[..file_name.len() - 3] } else { file_name };
        format!("js/plugins/{}", stripped)
    }

    pub fn digested_logical_path_for(_plugin_directory_name: &str, _entrypoint_name: &str) -> Option<String> { None }
    pub fn import_paths_for(_plugin_directory_name: &str, _entrypoint_name: &str) -> Vec<String> { vec![] }
    pub fn external_plugin_imports(_plugin_directory_name: &str, _entrypoint_name: &str) -> Option<String> { None }
    pub fn route_bundle_for_path(_plugin_directory_name: &str, _entrypoint_name: &str, _path: Option<&str>) -> Option<String> { None }

    pub fn url_glob_pattern(glob: &str) -> String {
        let glob_stripped = if glob.ends_with("/*") { &glob[..glob.len() - 2] } else { glob };
        let segments: Vec<String> = glob_stripped.split('/')
            .map(|segment| match segment {
                "**" => "[^/]+(?:/[^/]+)*".to_string(),
                "*" => "[^/]+".to_string(),
                _ => regex::escape(segment),
            }).collect();
        format!("^{}(?:/.*)?$", segments.join("/"))
    }

    pub fn compile() {}
    pub fn compile_js_bundle(_plugin: &str) {}
    pub fn watch() {}
    pub fn production_build() -> bool { false }
    pub fn compress_to_brotli(_path: &str) -> Option<u64> { None }
    pub fn cache() -> bool { true }
    pub fn log(message: &str) { eprintln!("{}", message); }
    pub fn get_set_cache(_key: &str) {}
    pub fn has_source_files_in_dir(_plugin_directory_name: &str, _dir: &str) -> bool { false }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_optional_plugin_stub() {
        let stub = JsManager::optional_plugin_stub();
        assert!(stub.contains("autogenerated missing optional plugin stub"));
    }

    #[test]
    fn test_required_plugin_stub() {
        let stub = JsManager::required_plugin_stub("my-plugin");
        assert!(stub.contains("autogenerated missing required plugin stub"));
        assert!(stub.contains("my-plugin"));
    }

    #[test]
    fn test_logical_path() {
        assert_eq!(JsManager::logical_path("test-bundle.js"), "js/plugins/test-bundle");
        assert_eq!(JsManager::logical_path("test-bundle"), "js/plugins/test-bundle");
    }

    #[test]
    fn test_url_glob_pattern() {
        assert_eq!(JsManager::url_glob_pattern("admin/plugins/*"), "^admin/plugins(?:/.*)?$");
        assert_eq!(JsManager::url_glob_pattern("admin/**/test/*"), "^admin/[^/]+(?:/[^/]+)*/test(?:/.*)?$");
    }
}
